for c in chapters:
 ids=list(dict.fromkeys(c.pop('character_ids')))
 c['characters']=[{'id':pid,'name':people[pid][0],'role':people[pid][1],'group':people[pid][2]} for pid in ids]
 c['links']=[{'from':a,'to':b,'kind':k} for a,b,k in c['links'] if a in ids and b in ids]
 c['events']=[{'time':t,'title':name,'text':desc,'kind':kind} for t,name,desc,kind in c['events']]
 c['mysteries']=[{'id':id,'title':name,'question':q,'kind':k} for id,name,q,k in c['mysteries']]
 (root/'chapters'/f'ep{c["id"]:02d}.json').write_text(json.dumps(c,ensure_ascii=False,indent=2),encoding='utf-8')
